# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ULUSLARARASI RAPORLAR VE AMASYA GÖRÜŞMELERİ (EKİM 1919)</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Amiral Bristol Raporu</text>\n  <text x="38" y="96" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Bölge:</tspan> İzmir ve Batı Anadolu</text>\n  <text x="38" y="118" font-size="11" fill="#1e3a8a">• Yunan işgalinin haksızlığını ve</text>\n  <text x="46" y="134" font-size="11" fill="#1e3a8a">Türk nüfus çoğunluğunu tespit etti.</text>\n  <text x="38" y="158" font-size="11" font-weight="bold" fill="#1d4ed8">• Önemi: Millî Mücadele\'nin</text>\n  <text x="46" y="174" font-size="11" font-weight="bold" fill="#1d4ed8">haklılığını kanıtlayan ilk</text>\n  <text x="46" y="190" font-size="11" font-weight="bold" fill="#1d4ed8">uluslararası resmî belgedir.</text>\n\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">General Harbord Raporu</text>\n  <text x="260" y="96" font-size="11" fill="#14532d">• <tspan font-weight="bold">Bölge:</tspan> Doğu Anadolu ve Sivas</text>\n  <text x="260" y="118" font-size="11" fill="#14532d">• Mustafa Kemal Paşa ile Sivas\'ta</text>\n  <text x="268" y="134" font-size="11" fill="#14532d">bizzat görüşüldü.</text>\n  <text x="260" y="158" font-size="11" font-weight="bold" fill="#15803d">• Önemi: Doğu Anadolu\'daki</text>\n  <text x="268" y="174" font-size="11" font-weight="bold" fill="#15803d">Ermeni çoğunluk ve katliam</text>\n  <text x="268" y="190" font-size="11" font-weight="bold" fill="#15803d">iddialarını çürüttü.</text>\n\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Amasya Görüşmeleri</text>\n  <text x="483" y="96" font-size="11" fill="#78350f">• <tspan font-weight="bold">Tarih:</tspan> 20-22 Ekim 1919</text>\n  <text x="483" y="118" font-size="11" fill="#78350f">• Mustafa Kemal Paşa (Temsil H.)</text>\n  <text x="491" y="134" font-size="11" fill="#78350f">&amp; Salih Paşa (İstanbul Hük.)</text>\n  <text x="483" y="158" font-size="11" font-weight="bold" fill="#b45309">• Sonuç: İstanbul Hükûmeti,</text>\n  <text x="491" y="174" font-size="11" font-weight="bold" fill="#b45309">Temsil Heyeti\'ni resmen</text>\n  <text x="491" y="190" font-size="11" font-weight="bold" fill="#b45309">ve hukuken tanıdı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ANKARA\'NIN SEÇİLME NEDENLERİ VE MEBUSAN MECLİSİ SÜRECİ</text>\n  <rect x="25" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="185" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Ankara\'nın Merkez Seçilme Nedenleri</text>\n  <text x="40" y="96" font-size="12" fill="#14532d">• <tspan font-weight="bold">Coğrafi Güvenlik:</tspan> Anadolu\'nun ortasında,</text>\n  <text x="50" y="114" font-size="11" fill="#14532d">işgal tehdidinden uzak stratejik konum</text>\n  <text x="40" y="138" font-size="12" fill="#14532d">• <tspan font-weight="bold">Ulaşım ve İletişim:</tspan> İstanbul\'a giden</text>\n  <text x="50" y="156" font-size="11" fill="#14532d">demir yolu hattı ve telgraf ağı üzerinde olması</text>\n  <text x="40" y="180" font-size="12" fill="#14532d">• <tspan font-weight="bold">Cepheye Yakınlık:</tspan> Batı Cephesi\'ne yakınlık</text>\n  <text x="40" y="204" font-size="12" fill="#14532d">• <tspan font-weight="bold">Askeri Güç:</tspan> 20. Kolordu ve halkın tam desteği</text>\n\n  <rect x="365" y="45" width="310" height="195" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">Son Osmanlı Mebusan Meclisi (12 Ocak 1920)</text>\n  <text x="380" y="96" font-size="12" fill="#581c87">• <tspan font-weight="bold">İstenen Grup:</tspan> Müdafaa-i Hukuk Grubu</text>\n  <text x="380" y="120" font-size="12" fill="#581c87">• <tspan font-weight="bold">Kurulan Grup:</tspan> Felah-ı Vatan Grubu (Rauf Bey)</text>\n  <rect x="380" y="136" width="280" height="86" rx="6" fill="#ffffff" stroke="#c084fc" stroke-width="1.5"/>\n  <text x="520" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">28 Ocak 1920 — MİSAK-I MİLLÎ (Millî Ant)</text>\n  <text x="520" y="178" text-anchor="middle" font-size="11" fill="#581c87">Erzurum ve Sivas Kongresi kararları meclis</text>\n  <text x="520" y="196" text-anchor="middle" font-size="11" fill="#581c87">tarafından resmen kabul edilerek Türk milletinin</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">kabul edebileceği asgari barış şartları ilan edildi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MİSAK-I MİLLÎ KONULARI (KAPSAB) VE BMM\'NİN AÇILIŞ SÜRECİ</text>\n  <!-- Sol: Misak-i Milli -->\n  <rect x="25" y="45" width="340" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="195" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Misak-ı Millî Kararları (28 Ocak 1920)</text>\n  <text x="40" y="93" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">K - Kapitülasyonlar:</tspan> Siyasi, adli, mali kısıtlamalar reddedildi.</text>\n  <text x="40" y="114" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">A - Azınlıklar:</tspan> Komşu ülkelerdeki Müslüman haklarıyla eşitlik.</text>\n  <text x="40" y="135" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">P - Plebisit (Referandum):</tspan> Kars-Ardahan-Batum, Batı</text>\n  <text x="50" y="150" font-size="11" fill="#1e3a8a">Trakya ve Arap topraklarında halk oylaması.</text>\n  <text x="40" y="171" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">S - Sınırlar:</tspan> Mondros öncesi Türk-İslam çoğunluğu bütündür.</text>\n  <text x="40" y="192" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">B - Boğazlar:</tspan> Güvenlik şartıyla dünya ticaretine açık.</text>\n  <text x="40" y="216" font-size="11" font-weight="bold" fill="#1d4ed8">Not: Misak-ı Millî\'de \'millî bağımsızlık\' ön plandadır.</text>\n\n  <!-- Sag: 16 Mart -> 23 Nisan -->\n  <rect x="380" y="45" width="295" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="527" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">İstanbul\'un İşgali ve BMM\'nin Açılışı</text>\n  <rect x="395" y="84" width="265" height="62" rx="6" fill="#ffffff" stroke="#f87171" stroke-width="1.5"/>\n  <text x="527" y="104" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">16 Mart 1920 — İstanbul\'un Resmen İşgali</text>\n  <text x="527" y="122" text-anchor="middle" font-size="11" fill="#7f1d1d">Mebusan Meclisi dağıtıldı, millî iradeye</text>\n  <text x="527" y="138" text-anchor="middle" font-size="11" fill="#7f1d1d">darbe vuruldu, mebuslar Malta\'ya sürüldü.</text>\n\n  <rect x="395" y="158" width="265" height="66" rx="6" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="527" y="178" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">23 Nisan 1920 — BMM\'nin Açılışı (Ankara)</text>\n  <text x="527" y="196" text-anchor="middle" font-size="11" fill="#14532d">Temsil Heyeti\'nin görevi sona erdi; yeni</text>\n  <text x="527" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Türk devleti ve millî egemenlik kuruldu.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
